import{_ as i,o,c as t,ag as a}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"Accessibility","description":"","frontmatter":{},"headers":[],"relativePath":"kit/accessibility.md","filePath":"kit/accessibility.md"}'),s={name:"kit/accessibility.md"};function d(n,e,r,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h1><p>fewui implements the WAI-ARIA Authoring Practices patterns by hand (it does not wrap a headless primitive library). This page states what the components do for you, and what remains your responsibility.</p><h2 id="what-components-guarantee" tabindex="-1">What components guarantee <a class="header-anchor" href="#what-components-guarantee" aria-label="Permalink to &quot;What components guarantee&quot;">​</a></h2><h3 id="modal-layers-—-ui-dialog-ui-sheet-ui-confirm-dialog-ui-command" tabindex="-1">Modal layers — <code>ui-dialog</code>, <code>ui-sheet</code>, <code>ui-confirm-dialog</code>, <code>ui-command</code> <a class="header-anchor" href="#modal-layers-—-ui-dialog-ui-sheet-ui-confirm-dialog-ui-command" aria-label="Permalink to &quot;Modal layers — `ui-dialog`, `ui-sheet`, `ui-confirm-dialog`, `ui-command`&quot;">​</a></h3><ul><li><code>role=&quot;dialog&quot;</code> + <code>aria-modal</code>, labelled by the title and described by the description.</li><li>Focus moves into the layer when it opens and returns to the opener when it closes.</li><li>Tab cycles inside the layer. If focus lands on the page behind it (mouse, screen-reader navigation, a programmatic <code>focus()</code>), it is pulled back.</li><li>Escape closes only the topmost layer: an open select or menu inside a dialog closes first, the dialog on the next press.</li><li>Background scrolling is locked while a modal layer is open.</li></ul><p>Focus containment deliberately leaves alone: layers opened from the modal (popover, select, date picker), toasts, third-party widgets appended to <code>&lt;body&gt;</code>, other <code>aria-modal</code> dialogs, and anything marked <code>data-ui-focus-allow</code>.</p><h3 id="floating-layers-—-ui-popover-ui-dropdown-ui-select-pickers-ui-context-menu-ui-menubar" tabindex="-1">Floating layers — <code>ui-popover</code>, <code>ui-dropdown</code>, <code>ui-select</code>, pickers, <code>ui-context-menu</code>, <code>ui-menubar</code> <a class="header-anchor" href="#floating-layers-—-ui-popover-ui-dropdown-ui-select-pickers-ui-context-menu-ui-menubar" aria-label="Permalink to &quot;Floating layers — `ui-popover`, `ui-dropdown`, `ui-select`, pickers, `ui-context-menu`, `ui-menubar`&quot;">​</a></h3><ul><li><strong>Select</strong>: <code>listbox</code> / <code>option</code>, <code>aria-activedescendant</code>, arrows, Home/End, PageUp/PageDown, type-ahead.</li><li><strong>Menus</strong>: <code>menu</code> / <code>menuitem</code> / <code>menuitemcheckbox</code> / <code>menuitemradio</code>, submenus with <code>aria-haspopup</code> and <code>aria-expanded</code>, arrows, Home/End, type-ahead, Tab closes and returns focus.</li><li><strong>Popover and dropdown triggers</strong>: the <code>#trigger</code> slot exposes <code>triggerAttrs</code> (<code>aria-haspopup</code>, <code>aria-expanded</code>, <code>aria-controls</code>). Bind it to your trigger button:</li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-dropdown</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;items&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> #trigger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{ toggle, triggerAttrs }&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-bind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;triggerAttrs&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> @click</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;toggle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Seçenekler&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-dropdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><strong>Tooltip</strong>: <code>role=&quot;tooltip&quot;</code>, linked to the trigger with <code>aria-describedby</code> while open (skipped when the tooltip text equals the trigger&#39;s accessible name, so it is not read twice), shown on hover and focus, dismissed with Escape.</li></ul><h3 id="composite-widgets" tabindex="-1">Composite widgets <a class="header-anchor" href="#composite-widgets" aria-label="Permalink to &quot;Composite widgets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Pattern</th></tr></thead><tbody><tr><td><code>ui-tabs</code></td><td><code>tablist</code> / <code>tab</code> / <code>tabpanel</code>, roving tabindex, arrows, Home/End</td></tr><tr><td><code>ui-accordion</code></td><td>header buttons with <code>aria-expanded</code> / <code>aria-controls</code>, <code>region</code> panels, arrows, Home/End</td></tr><tr><td><code>ui-segment-group</code>, <code>ui-radio-group</code>, <code>ui-chip-group</code></td><td><code>radiogroup</code> / <code>radio</code> with roving tabindex</td></tr><tr><td><code>ui-slider</code> (range)</td><td>one <code>slider</code> per thumb with min/max/now/text</td></tr><tr><td><code>ui-resizable-handle</code></td><td><code>separator</code> with value attributes; arrows, Home/End, Enter to collapse</td></tr><tr><td><code>ui-pagination</code>, <code>ui-breadcrumb</code></td><td><code>nav</code> landmark, <code>aria-current=&quot;page&quot;</code></td></tr><tr><td><code>ui-date-picker</code></td><td>labelled day buttons, roving tabindex, arrows by day/week, Home/End, PageUp/PageDown by month</td></tr><tr><td><code>ui-chart</code></td><td><code>role=&quot;img&quot;</code> with a label, a visually hidden data table, keyboard-readable values</td></tr></tbody></table><h3 id="status-messages" tabindex="-1">Status messages <a class="header-anchor" href="#status-messages" aria-label="Permalink to &quot;Status messages&quot;">​</a></h3><p><code>ui-toast</code> announces through two live regions that exist before any toast is shown: <code>polite</code> for information, <code>assertive</code> for the <code>danger</code> tone. Toasts do not auto-dismiss while the pointer or keyboard focus is on them.</p><h3 id="motion-and-direction" tabindex="-1">Motion and direction <a class="header-anchor" href="#motion-and-direction" aria-label="Permalink to &quot;Motion and direction&quot;">​</a></h3><p>Animations are reduced or removed under <code>prefers-reduced-motion</code>. Right-to-left is covered in <a href="./localization.html">Localization &amp; RTL</a>.</p><h2 id="what-stays-your-job" tabindex="-1">What stays your job <a class="header-anchor" href="#what-stays-your-job" aria-label="Permalink to &quot;What stays your job&quot;">​</a></h2><ul><li><strong>Names.</strong> Icon-only buttons need <code>aria-label</code>; popovers used as dialogs need <code>aria-label</code> on <code>ui-popover</code>; charts need <code>aria-label</code>.</li><li><strong>Form labels.</strong> Put every control in <code>ui-form-row</code>; it wires the label, description and error to the control.</li><li><strong>Contrast of your theme.</strong> Token helpers (<code>ensureContrastForMode</code>, <code>pickContrastForeground</code>) derive readable foregrounds, but a custom palette should still be checked.</li><li><strong>Content order and headings</strong> in your pages.</li></ul><h2 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h2><ul><li><code>ui-date-picker</code> exposes days as labelled buttons in a named group, not as an ARIA <code>grid</code>.</li><li>Not yet verified with a real screen reader, or in Firefox and Safari.</li><li>Bar and area charts distinguish series by colour and legend only; line charts also use dash patterns.</li></ul>',20)])])}const g=i(s,[["render",d]]);export{u as __pageData,g as default};
